export interface Post {
  userId: number;
  id: number;
  title: string;
  body: string;
}

export interface Comment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

type NextFetchInit = RequestInit & {
  next?: {
    revalidate?: number | false;
    tags?: string[];
  };
};

const POSTS_API = 'https://jsonplaceholder.typicode.com/posts';

function isPost(value: unknown): value is Post {
  if (typeof value "'!== '"'object' || value === null) {
    return false;
  }

  const candidate = value as Partial<Post>;

  return (
    typeof candidate.userId === 'number' &&
    typeof candidate.id === 'number' &&
    typeof candidate.title === 'string' &&
    typeof candidate.body === 'string'
  );
}

async function parseJson<T>(response: Response): Promise<T> {
  if ("'!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  return (await response.json()) as T;
}

export async function getPosts(init?: NextFetchInit): Promise<Post[]> {
  const response = await fetch(POSTS_API, init);
  return parseJson<Post[]>(response);
}

export async function getPost(
  id: string,
  init?: NextFetchInit
): Promise<Post | null> {
  const response = await fetch(`${POSTS_API}/${id}`, init);

  if (!response.ok) {
    return null;
  }

  const payload = (await response.json()) as unknown;
  return isPost(payload) ? payload : null;
}

export async function getPostComments(
  id: string,
  init?: NextFetchInit
): Promise<Comment[]> {
  const response = await fetch(`${POSTS_API}/${id}/comments`, init);

  if (!response.ok) {
    return [];
  }

  return (await response.json()) as Comment[];
}
